import {renderMarkdown} from './reports.js';
const css=document.createElement('style');css.textContent=`#run-output-dialog{width:min(1000px,94vw);height:86vh;box-sizing:border-box;border:1px solid #d3d7cd;border-radius:18px;padding:24px;background:#faf6ed;color:#1c3338;overflow:hidden}#run-output-dialog::backdrop{background:#172d3866;backdrop-filter:blur(4px)}#run-output-dialog .output-head{display:flex;align-items:center;justify-content:space-between;gap:14px}#run-output-dialog h2{margin:0;font-size:23px}#run-output-dialog button,#run-output-dialog select{padding:9px 12px;border:1px solid #cbd1c7;border-radius:8px;background:#fff9;color:inherit;cursor:pointer}#output-controls{display:flex;gap:10px;margin:16px 0}#output-controls select{width:auto;max-width:60%}#output-body{overflow:auto;height:calc(100% - 135px);font-size:14px;line-height:1.85;overflow-wrap:anywhere}#output-body p{white-space:pre-wrap}#output-body h1{font-size:25px}#output-body h2{font-size:21px;margin-top:22px}#output-body li{list-style-position:inside;margin:8px 0}#output-body a{color:#316e85;text-decoration:underline}#output-source{font-size:12px;color:#687973;margin:8px 0}#output-body pre{white-space:pre-wrap}`;document.head.append(css);
const dialog=document.createElement('dialog');dialog.id='run-output-dialog';dialog.setAttribute('aria-label','完整执行结果');dialog.innerHTML='<div class="output-head"><h2 id="output-title">完整结果</h2><button id="output-close">关闭</button></div><p id="output-source">Agent 最终回复原文，不等同于独立验收。</p><div id="output-controls"><select id="output-attempt" aria-label="执行批次"></select><button id="output-refresh">刷新</button><button id="output-download" hidden>下载全文</button></div><article id="output-body" aria-live="polite"></article>';document.body.append(dialog);const $=s=>dialog.querySelector(s);let id=0,version=0,data=null,current=null;
function show(){current=data?.attempts.find(a=>a.attempt===Number($('#output-attempt').value))?.output;$('#output-download').hidden=!current;const body=$('#output-body');body.replaceChildren();if(current){renderMarkdown(current.text,body);if(current.truncated){const note=document.createElement('p');note.textContent='此回复超过显示上限，当前正文为截取内容。';body.prepend(note);}body.scrollTop=0;}else{const p=document.createElement('p');p.textContent=data?.message||'本次执行没有留下最终回复。';body.append(p);}}
async function refresh(){const token=++version;current=null;$('#output-download').hidden=true;$('#output-attempt').replaceChildren();$('#output-body').textContent='正在读取完整回复…';try{const response=await fetch('/api/runs/'+id+'/output');if(!response.ok)throw Error('完整结果读取失败，请稍后重试。');const result=await response.json();if(token!==version)return;data=result;for(const attempt of data.attempts){const option=document.createElement('option');option.value=attempt.attempt;option.textContent='第 '+attempt.attempt+' 次执行'+(attempt.output?' · 已有最终回复':' · 无最终回复');$('#output-attempt').append(option);}show();}catch(e){if(token===version)$('#output-body').textContent=e.message;}}
export function openRunOutput(run){id=Number(run);$('#output-title').textContent='第 '+id+' 轮 · 完整结果';if(!dialog.open)dialog.showModal();refresh();}
$('#output-close').onclick=()=>dialog.close();dialog.onclose=()=>{version++;};$('#output-refresh').onclick=refresh;$('#output-attempt').onchange=show;$('#output-download').onclick=()=>{if(!current)return;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([current.text],{type:'text/markdown;charset=utf-8'}));a.href=url;a.download='run-'+id+'-result'+(current.truncated?'-excerpt':'')+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};document.addEventListener('click',e=>{const b=e.target.closest('[data-run-output]');if(b)openRunOutput(b.dataset.runOutput);});
